#!/usr/bin/env python3
"""Source-bound draft expansions of §§1–9. Original overview cards are never rewritten.
Printed pages = PDF pages minus one. Includes §7 articles and proofs pp.73–79.
All source/mathematics/pedagogy review flags remain pending.
"""
import json, math, hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[2]; OUT=R/'stereo-course/merzlyak-10-base/lessons'; SQ=math.sqrt
CARDS=[]; COUNTS={}
def v(label,segments=None,polygon=None,points=None):
 d={'label':label}
 for k,x in [('segments',segments),('polygon',polygon),('points',points)]:
  if x:d[k]=x
 return d
def model(p,e,faces=None,views=None,labels=None):
 d={'points':{k:list(x) for k,x in p.items()},'edges':e,'views':{'neutral':v('Условие и обозначения'),**(views or {})},'labelNames':labels or [k for k in p if not k.startswith('_')]}
 if faces:d['faces']=faces
 return d
def view(m,k,label,segs=None,poly=None,pts=None):m['views'][k]=v(label,segs,poly,pts)
def step(title,text,view='neutral',why='Аксиомы и теоремы, указанные в рассуждении.'):
 return {'title':title,'prompt':title+': объясни этот переход до открытия разбора.','explanation':text,'justifications':[{'kind':'theorem','text':why}],'view':view}
def lerp(a,b,t):return [x+t*(y-x) for x,y in zip(a,b)]
def edgepoly(poly):return [[poly[i],poly[(i+1)%len(poly)]] for i in range(len(poly))]
def box():
 p={'A':[0,0,0],'B':[3,0,0],'C':[3,3,0],'D':[0,3,0],'A1':[0,0,3],'B1':[3,0,3],'C1':[3,3,3],'D1':[0,3,3]}
 return model(p,edgepoly(['A','B','C','D'])+edgepoly(['A1','B1','C1','D1'])+[[x,x+'1'] for x in 'ABCD'],[['A','B','C','D'],['A1','B1','C1','D1']])
def tetra():return model({'A':[0,0,0],'B':[4,0,0],'C':[1,3,0],'D':[1,1,4]},[['A','B'],['B','C'],['C','A'],['D','A'],['D','B'],['D','C']],[['A','B','C']])
def prism():
 p={'A':[0,0,0],'B':[4,0,0],'C':[1,3,0],'A1':[.5,.4,3],'B1':[4.5,.4,3],'C1':[1.5,3.4,3]}
 return model(p,edgepoly(['A','B','C'])+edgepoly(['A1','B1','C1'])+[[x,x+'1'] for x in 'ABC'],[['A','B','C'],['A1','B1','C1']])
def plane_lines():
 p={'O':[0,0,0],'A':[3,0,0],'B':[0,3,0],'C':[3,3,0],'O1':[.5,.5,2],'A1':[3.5,.5,2],'B1':[.5,3.5,2],'C1':[3.5,3.5,2]}
 return model(p,[['O','A'],['O','B'],['O1','A1'],['O1','B1']],[['O','A','C','B'],['O1','A1','C1','B1']],{'lower':v('Два пересекающихся направления',segments=[['O','A'],['O','B']]),'upper':v('Параллельные направления через внешнюю точку',segments=[['O1','A1'],['O1','B1']])})
def crossplanes():
 p={'P':[-2,0,0],'Q':[2,0,0],'A':[-2,2,0],'B':[2,2,0],'C':[-2,0,2],'D':[2,0,2]}
 return model(p,[['P','Q'],['A','B'],['C','D']],[['P','Q','B','A'],['P','Q','D','C']],{'first':v('Первая плоскость',polygon=['P','Q','B','A']),'second':v('Вторая плоскость',polygon=['P','Q','D','C']),'directions':v('Три параллельных направления',segments=[['P','Q'],['A','B'],['C','D']])})
def save(p,part,pages,title,statement,m,steps,hint,caption=None):
 COUNTS[p]=COUNTS.get(p,0)+1;n=COUNTS[p];ident=f'merz-theory-{p:02}-detail-{n:02}';file=f'theory-{p:02}-detail-{n:02}.json'
 if p==3 or (p==5 and n in [4,5]):m['labelNames']=[k for k in m['points'] if not k.startswith('_')]
 chapter='Глава 1. Введение в стереометрию' if p<=3 else 'Глава 2. Параллельность в пространстве' if p<=7 else 'Глава 3. Перпендикулярность в пространстве'
 d={'schemaVersion':1,'revision':1,'id':ident,'kind':'theory','title':f'§ {p}. {title}','status':'draft','source':{'bookId':'merzlyak-2022-10-base','collection':'theory','point':str(p),'subpart':part,'chapter':chapter,'printedPages':pages,'pdfPages':[x+1 for x in pages]},'statement':{'text':statement,'goal':'Восстанови рассуждение по модели, затем запиши своё обоснование.'},'visualization':{'type':'scene3d','caption':caption or 'Модель показывает конкретную допустимую конфигурацию. Доказательство относится ко всем случаям, указанным в условии. Прямые и плоскости продолжаются за показанные фрагменты; длины и углы по экрану не измеряют.','model':m},'help':[{'id':'help-1','question':'Как начать рассуждение?','text':hint}],'steps':[dict(s,id=f'step-{i+1}') for i,s in enumerate(steps)],'answer':{'mode':'manual','prompt':'Запиши доказательство или построение своими словами, указывая условия применённых теорем. Запись сохраняется; доказательство автоматически не оценивается.'},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 path=OUT/file;path.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');CARDS.append({'paragraph':p,'sourceId':f'source-theory-{p:02}','part':part,'printedPages':pages,'pdfPages':[x+1 for x in pages],'lessonId':ident,'file':str(path.relative_to(R)),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})

# §1 is already complete in the six overview steps; the source task on p.10
# is the direct A4 consequence explicitly explained in overview step-6.
m=model({'M':[0,0,0],'A':[3,0,0],'B':[0,3,0],'C':[3,3,0]},[['M','A'],['M','B']],[['M','A','C','B']],{'points':v('Точка вне второй прямой',points=['M','A','B']),'plane':v('Единственная плоскость',polygon=['M','A','C','B'])})
save(2,'доказательство теоремы 2.2',[14],'Две пересекающиеся прямые задают плоскость','Прямые a и b пересекаются в M. Докажи существование и единственность плоскости через них. На модели a=MA, b=MB.',m,[step('Выберем внешнюю точку','Возьмём A∈a, A≠M. Тогда A∉b: иначе две различные прямые a,b имели бы две общие точки и совпали.','points'),step('Построим плоскость','По теореме 2.1 через b и внешнюю точку A проходит плоскость α. Точки M,A принадлежат α, поэтому по A3 вся a лежит в α. Существование доказано.','plane'),step('Докажем единственность','Любая плоскость β через a,b содержит b и A. Теорема 2.1 допускает лишь одну плоскость через такую прямую и внешнюю точку; значит β=α.','plane')],'Используй теорему о прямой и внешней точке дважды: для существования и для единственности.')

# §3: named solids and all three embedded constructions.
p={k:[2*math.cos(2*math.pi*i/5),2*math.sin(2*math.pi*i/5),0] for i,k in enumerate('ABCDE')};p['F']=[0,0,3]
m=model(p,edgepoly(list('ABCDE'))+[['F',k] for k in 'ABCDE'],[list('ABCDE')],{'base':v('Пятиугольное основание',polygon=list('ABCDE')),'side':v('Боковая грань FAB',polygon=['F','A','B'])})
save(3,'многогранники и примеры сечений',[16,17,18,19],'Грани, рёбра, вершины и сечения','Разбери названия частей пятиугольной пирамиды FABCDE и сопоставь её с призмой, прямоугольным параллелепипедом и кубом.',m,[step('Назовём части пирамиды','ABCDE — основание; FAB,FBC,FCD,FDE,FEA — пять боковых треугольных граней; F — вершина пирамиды. Вместе с основанием получаем 6 граней, 10 рёбер и 6 вершин.','side'),step('Сравним с призмами','У треугольной призмы два равных треугольных основания и три боковых параллелограмма: 5 граней, 9 рёбер, 6 вершин. У четырёхугольной призмы оснований по-прежнему два, боковых граней четыре: всего 6 граней, 12 рёбер, 8 вершин. Эта модель изображает именно пирамиду.','base'),step('Выделим частные случаи','Прямоугольный параллелепипед — многогранник с шестью прямоугольными гранями; если все они равные квадраты, получаем куб. Треугольная пирамида называется тетраэдром.','neutral'),step('Понимаем сечение как общую фигуру','Сечение многогранника плоскостью — многоугольник их общих точек. Его стороны лежат в гранях. Например, плоскость через F,A,C пересекает нашу пирамиду по треугольнику FAC; это не требует соединять произвольные точки разных граней.','cut')],'Сначала перечисли рёбра основания, затем по одному боковому ребру на каждую вершину основания.')
# Add the missing concrete view before the next serialization below.
path=OUT/'theory-03-detail-01.json';d=json.loads(path.read_text());d['visualization']['model']['views']['cut']=v('Диагональное сечение FAC',polygon=['F','A','C']);path.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');CARDS[-1]['sha256']=hashlib.sha256(path.read_bytes()).hexdigest()
m=box();m['points'].update({'M':[0,0,2],'N':[0,3,1],'X':[0,6,0]});m['edges'] += [['M','N'],['N','X'],['D','X']];view(m,'face','Прямая MN в плоскости AA₁D₁D',poly=['A','D','D1','A1']);view(m,'trace','Пересечение MN и AD',segs=[['M','X'],['A','X']],pts=['X'])
save(3,'задача 1: пересечение прямой с плоскостью',[18,19],'Продолжим прямую до основания куба','В кубе ABCDA₁B₁C₁D₁ точки M∈AA₁, N∈DD₁ удовлетворяют AM≠DN. Найди пересечение MN с плоскостью ABC.',m,[step('Найдём общую плоскость','M,N,A,D лежат в плоскости грани AA₁D₁D. Её пересечение с плоскостью ABC — AD. Поэтому искать надо пересечение MN с AD.','face'),step('Проверим, что пересечение существует','Если бы MN∥AD, то в этой плоской фигуре MNDA был бы параллелограммом и AM=DN. Это исключено условием. Значит, MN и AD пересекаются в некоторой точке X. В модели X находится на продолжении AD за D.','trace'),step('Проверим ответ','X∈MN и X∈AD⊂(ABC). MN не лежит в основании, поэтому общей может быть только одна точка. Искомая точка — X.','trace')],'Не проводи произвольную линию к основанию: сначала используй грань, в которой уже лежат M и N.')
m=tetra();p=m['points'];p.update({'M':lerp(p['A'],p['D'],.5),'N':lerp(p['B'],p['D'],.25),'K':lerp(p['A'],p['C'],.5)});p['X']=[6,0,0];p['P']=lerp(p['B'],p['C'],.25);m['edges'] += [['M','N'],['N','X'],['B','X'],['K','X'],['K','M'],['N','P']];view(m,'trace','След секущей плоскости на основании',segs=[['M','X'],['A','X'],['K','X']],pts=['X']);view(m,'section','Сечение KMNP',poly=['K','M','N','P'])
save(3,'задача 2: сечение тетраэдра по следу',[20],'Сечение тетраэдра по трём точкам','В тетраэдре DABC точки M,N,K лежат соответственно на AD,DB,AC; MN не параллельна AB. Построй сечение плоскостью KMN.',m,[step('Две стороны уже видны','KM лежит в грани ADC, MN — в грани ADB. Обе прямые принадлежат секущей плоскости.','section'),step('Найдём точку на следе','В плоскости ADB продолжим MN и AB до X. Так как MN∦AB, пересечение существует. X лежит одновременно в секущей плоскости и в основании ABC.','trace'),step('Проведём след','K тоже лежит в основании и секущей плоскости. Поэтому KX — линия их пересечения. Обозначим P=KX∩BC и соединим P с N.','trace'),step('Замкнём сечение','KP лежит в ABC, PN — в DBC, NM — в DAB, MK — в DAC. Таким образом, KMNP — искомый четырёхугольник. На модели все M,N,K,P находятся внутри соответствующих рёбер.','section')],'Продли известную сторону сечения до прямой основания; это даст вторую точку следа.')
m=prism();p=m['points'];p.update({'M':lerp(p['B'],p['B1'],.6),'K':lerp(p['A'],p['A1'],.3),'N':lerp(p['C'],p['C1'],.4),'X':[-4,0,0],'Y':[-5,9,0]});m['edges'] += [['M','X'],['M','Y'],['X','Y'],['A','X'],['C','Y'],['K','N']];view(m,'trace','Заданная прямая a=XY в основании',segs=[['X','Y'],['X','B'],['Y','B']],pts=['X','Y']);view(m,'section','Сечение KMN',poly=['K','M','N'])
save(3,'задача 3: сечение призмы по прямой и точке',[20,21],'Сечение треугольной призмы','Даны треугольная призма ABCA₁B₁C₁, точка M на BB₁ и прямая a в плоскости основания ABC, расположенная как на рисунке учебника. Построй сечение плоскостью через a и M.',m,[step('Пересечём прямую с рёбрами основания','Обозначим X=a∩AB и Y=a∩BC, продолжая рёбра при необходимости. На модели обе точки находятся на продолжениях за A и C.','trace'),step('Первая боковая грань','В грани ABB₁A₁ секущая плоскость содержит M и X. Проведём MX; точка K=MX∩AA₁ даёт вторую вершину сечения.','section'),step('Вторая боковая грань','Аналогично проведём MY в плоскости BCC₁B₁. Получим N=MY∩CC₁.','section'),step('Третья грань и проверка','K и N принадлежат грани ACC₁A₁ и секущей плоскости. Соединяем KN. В изображённом расположении точки K,M,N лежат на рёбрах призмы и сечение — треугольник KMN. Для иного положения a нужно заново проверить, на каких рёбрах лежат пересечения.','section')],'Используй по две точки секущей плоскости в каждой боковой грани.')

# §4.
m=model({'P':[-2,0,0],'Q':[2,0,0],'A':[0,2,0],'B':[2,2,0],'C':[-2,2,0]},[['P','Q'],['C','B']],[['P','Q','B','C']],{'plane':v('Плоскость через a и A',polygon=['P','Q','B','C']),'parallel':v('Параллель через A',segments=[['P','Q'],['C','B']],points=['A'])})
save(4,'доказательство теоремы 4.2',[34,35],'Единственная параллельная через внешнюю точку','Даны прямая a и точка A∉a. Докажи, что через A проходит ровно одна прямая, параллельная a. В модели a=PQ.',m,[step('Существование в одной плоскости','Прямая a и внешняя точка A задают единственную плоскость α. В ней по аксиоме параллельности планиметрии существует прямая b через A, параллельная a.','plane'),step('Почему другая плоскость не поможет','Если ещё одна прямая b₁ проходит через A и параллельна a, то по определению параллельности a,b₁ лежат в общей плоскости β. Но β содержит a и A, поэтому по теореме 2.1 β=α.','plane'),step('Единственность','Обе предполагаемые параллельные лежат в α и проходят через A. По планиметрической аксиоме они совпадают. Значит, пространственная параллель через A тоже единственна. Отрезки называют параллельными или скрещивающимися, когда таковы содержащие их прямые.','parallel')],'Параллельность уже гарантирует общую плоскость; докажи, что это та же самая плоскость α.')
m=model({'P':[0,-2,0],'Q':[0,3,0],'A':[-2,0,0],'B':[2,0,0],'M':[0,2,0],'C':[-2,2,0],'D':[2,2,0],'E':[-2,-1,0],'F':[2,-1,0]},[['P','Q'],['A','B'],['C','D'],['E','F']],[['E','F','D','C']],{'plane':v('Плоскость двух пересекающихся прямых',segments=[['P','Q'],['A','B']]),'family':v('Другие параллельные через точки m',segments=[['C','D'],['E','F']],points=['M'])})
save(4,'задача: параллельные прямые через данную прямую',[36],'Все проектирующие прямые лежат в одной плоскости','Докажи, что взаимно параллельные прямые, пересекающие данную прямую m, лежат в одной плоскости. В модели m=PQ, a=AB, b=CD.',m,[step('Зафиксируем плоскость','Выберем одну прямую семейства a. Пересекающиеся a,m задают единственную плоскость α.','plane'),step('Возьмём любую другую прямую','Пусть b∥a и b∩m={M}. M не принадлежит a: две различные параллельные прямые не имеют общей точки.','family'),step('Исключим выход из плоскости','Если b не лежит в α, она пересекает α только в M. Так как a⊂α и M∉a, признак скрещивающихся прямых делает a,b скрещивающимися. Это противоречит b∥a.','family'),step('Завершим доказательство','Значит, любая такая b лежит в одной и той же α. Именно это позволяет помещать проектирующие прямые всех точек одной прямой в общую плоскость.','plane')],'Предположи, что одна из параллельных выходит из плоскости a,m; примени признак скрещивания.')

# §5.
m=crossplanes()
save(5,'доказательство теоремы 5.3',[42,43],'Направление пересечения двух плоскостей','Через параллельные a,b проведены плоскости α,β; их пересечение c отлично и от a, и от b. Докажи c∥a и c∥b. Модель: a=AB, b=CD, c=PQ.',m,[step('Проверим обязательное условие','Прямая a не лежит в β: иначе она лежала бы в α∩β=c и совпала с c. Аналогично b не лежит в α. Условие c≠a,b нельзя пропускать.','directions'),step('Получим параллельность прямой плоскости','Из a∥b, b⊂β и a⊄β по признаку 5.1 следует a∥β.','second'),step('Применим свойство следа','Плоскость α содержит a и пересекает β по c. По теореме 5.2 a∥c. Меняя роли α,β и a,b, получаем b∥c. Отрезок называют параллельным плоскости, если содержащая его прямая параллельна этой плоскости.','directions')],'До применения признака 5.1 объясни, почему прямая a не принадлежит второй плоскости.')
m=crossplanes();m['points']['M']=[0,0,0];m['labelNames'].append('M')
save(5,'доказательство теоремы 5.4',[43],'Транзитивность параллельности в пространстве','Две различные прямые a,b параллельны прямой c. Докажи a∥b. В пространственной модели a=PQ, b=AB, c=CD; M∈a.',m,[step('Отделим плоский случай','Если все три прямые лежат в одной плоскости, утверждение следует из аксиомы параллельности планиметрии. Далее считаем, что общей плоскости у трёх прямых нет.','neutral'),step('Проведём две вспомогательные плоскости','Выберем M∈a. Прямые a,b не пересекаются: через их возможную общую точку прошли бы две параллельные c, что нарушает теорему 4.2. Поэтому M∉b,c. Зададим α=(b,M), β=(c,M).','first'),step('Рассмотрим их пересечение','Плоскости α,β различны: иначе содержащая b,c плоскость содержала бы и единственную параллель c через M, то есть a. Их линия пересечения a₁ проходит через M и отлична от b,c. По теореме 5.3 a₁∥b и a₁∥c.','directions'),step('Используем единственность параллельной','И a, и a₁ проходят через M и параллельны c. Теорема 4.2 даёт a=a₁. Следовательно a∥b.','directions')],'Сравни данную a с линией пересечения плоскостей (M,b) и (M,c).')
m=crossplanes();m['points'].update({'E':[-2,2,2],'F':[2,2,2]});m['edges'].append(['E','F']);m['labelNames']+=['E','F'];view(m,'external','Прямая a вне обеих плоскостей',segs=[['E','F'],['P','Q'],['A','B'],['C','D']])
save(5,'задача 1: прямая параллельна двум плоскостям',[43,44],'Параллельность общему следу','Прямая a параллельна двум пересекающимся плоскостям α,β. Докажи, что a параллельна их линии пересечения b. Модель: a=EF, b=PQ.',m,[step('Найдём направления внутри плоскостей','По следствию теоремы 5.2 в α найдётся прямая m∥a, а в β — n∥a. В модели это AB и CD.','external'),step('Проверим простой случай','Если m или n совпадает с b, сразу получаем a∥b. Далее считаем обе прямые отличными от b.','external'),step('Свяжем параллели','Из m∥a и n∥a по теореме 5.4 m∥n. По теореме 5.3 линия b пересечения плоскостей через m,n параллельна n.','directions'),step('Завершим','Теперь a∥n и b∥n. По теореме 5.4 a∥b. Условие a∥каждой плоскости означает отсутствие общих точек, а не принадлежность плоскости.','external')],'В каждой плоскости сначала найди прямую, параллельную a.')
m=prism();p=m['points'];p['M']=lerp(p['A1'],p['B1'],.4);p['N']=lerp(p['B1'],p['C1'],.6);m['edges'] += [['A','M'],['M','N'],['N','C'],['C','A']];view(m,'top','Параллель в верхнем основании',segs=[['M','N'],['A1','C1']]);view(m,'section','Четырёхугольник AMNC',poly=['A','M','N','C'])
save(5,'задача 2: сечение призмы через ребро',[44],'Параллельный след в призме','В треугольной призме ABCA₁B₁C₁ построй сечение через ребро AC и внутреннюю точку M ребра A₁B₁.',m,[step('Определим направление следа','AC∥A₁C₁, потому что ACC₁A₁ — параллелограмм. AC не лежит в верхнем основании, поэтому AC∥(A₁B₁C₁).','top'),step('Построим четвёртую вершину','Секущая плоскость содержит AC и M. По теореме 5.2 её след на верхнем основании проходит через M параллельно AC. Проведём MN∥A₁C₁ до N∈B₁C₁.','top'),step('Замкнём и проверим сечение','Соединим AM и NC в боковых гранях. AC,MN,AM,NC принадлежат секущей плоскости и соответствующим граням. Искомое сечение — AMNC.','section')],'В верхнем основании направление следа задано ребром AC, параллельным этому основанию.')
m=tetra();p=m['points'];p['M']=lerp(p['A'],p['D'],.5);p['N']=lerp(p['B'],p['D'],.5);p['P']=lerp(p['B'],p['C'],.6);p['K']=lerp(p['A'],p['C'],.6);m['edges']+=edgepoly(['K','M','N','P']);view(m,'midline','Средняя линия грани DAB',segs=[['M','N'],['A','B']]);view(m,'section','Сечение KMNP',poly=['K','M','N','P'])
save(5,'задача 3: сечение тетраэдра по средней линии',[44,45],'Сечение с параллельными сторонами','В тетраэдре DABC точки M,N — середины AD,BD; P — внутренняя точка BC. Построй сечение плоскостью MNP.',m,[step('Найдём известную параллель','MN — средняя линия треугольника DAB, поэтому MN∥AB. Так как MN не лежит в основании ABC, MN∥(ABC).','midline'),step('Построим след через P','Секущая плоскость содержит MN и P∈(ABC). По теореме 5.2 её след на основании параллелен MN. Через P проведём PK∥AB до K∈AC.','section'),step('Проверим границы','KM лежит в ADC, MN — в ADB, NP — в DBC, PK — в ABC. Все четыре отрезка лежат в плоскости MNP, значит KMNP — искомое сечение.','section')],'Середины двух рёбер дают среднюю линию; её параллельность определяет след на основании.')

# §6.
m=plane_lines()
save(6,'доказательство теоремы 6.2',[52,53],'Единственная параллельная плоскость','Через точку O₁ вне плоскости α проведи параллельную α плоскость и докажи её единственность. На модели α=(OAB).',m,[step('Два направления задают существование','В α выберем пересекающиеся a,b. Через внешнюю O₁ проведём a₁∥a и b₁∥b. Они различны и пересекаются в O₁, поэтому задают плоскость β. По признаку 6.1 β∥α.','upper'),step('Предположим вторую плоскость','Пусть через O₁ проходит ещё β₁∥α, β₁≠β. Тогда β∩β₁=c. Каждая из прямых a,b в α параллельна обеим плоскостям β,β₁.','lower'),step('Получим невозможные две параллели','По задаче 1 §5 a∥c и b∥c. Но a,b пересекаются и различны: через их точку пересечения не могут проходить две прямые, параллельные c. Следовательно β₁ не существует.','lower'),step('Применим к многоугольникам','Два многоугольника называют параллельными, когда параллельны содержащие их плоскости. Например, показанные четырёхугольники OACB и O₁A₁C₁B₁ лежат в таких плоскостях.','upper')],'Для единственности предположи две плоскости через O₁ и используй их общую прямую.')
p={'A':[0,0,0],'B':[4,0,0],'C':[4,4,0],'D':[0,4,0],'E':[2,2,4],'M':[3,3,2],'N':[4,2,0],'P':[0,2,0],'K':[1,3,2]}
m=model(p,edgepoly(list('ABCD'))+[['E',x] for x in 'ABCD']+edgepoly(['M','N','P','K']),[list('ABCD')],{'given':v('Плоскость ABE',polygon=['A','B','E']),'first':v('Первый след MN∥BE',segments=[['M','N'],['B','E']]),'section':v('Сечение MNPK',polygon=['M','N','P','K'])})
save(6,'задача 2: сечение пирамиды параллельно грани',[54],'Последовательно строим параллельные следы','В четырёхугольной пирамиде EABCD с выпуклым основанием точка M лежит внутри EC. Построй сечение через M, параллельное ABE. Модель показывает конфигурацию рис.6.10, где след через N пересекает AD; отдельно учти возможное пересечение с CD.',m,[step('Построим след в грани EBC','Параллельные плоскости пересекают EBC по параллельным прямым. Поэтому через M проводим MN∥BE до N∈BC.','first'),step('Перейдём в основание','Плоскость ABE пересекает ABCD по AB. След искомой плоскости через N должен быть параллелен AB: строим через N прямую, параллельную AB. В конфигурации модели она пересекает AD в P, как на рис.6.10. Для другого основания или положения M сначала выясняем, какое ребро пересечёт эта прямая.','section'),step('Замкнём сечение','В грани EAD через P проводим PK∥AE до K∈DE. Затем соединяем K с M в грани ECD. Получаем MNPK.','section'),step('Проверим параллельность','В полученной плоскости PN∥AB и NM∥BE. Это две пары соответствующих пересекающихся прямых; признак 6.1 даёт (PNM)∥(ABE). Значит, построение действительно задаёт требуемую плоскость.','given'),step('Другие положения следа','Если проведённая через N параллель AB пересекает ребро CD во внутренней точке T, то сечение — треугольник MNT: MN лежит в EBC, NT — в основании, TM — в ECD. Его плоскость параллельна ABE по NM∥BE и NT∥AB. Если след проходит через D, получается граничный треугольник MND. Поэтому нельзя заранее объявлять сечение четырёхугольником, не проверив, что след действительно попал на AD.','section')],'В каждой грани используй теорему о параллельных следах двух параллельных плоскостей.',caption='Модель показывает четырёхугольное сечение MNPK в конфигурации рис.6.10. В ином положении след может выйти на CD, тогда получается треугольник; этот случай разобран в последнем шаге. Плоскости продолжаются за показанные фрагменты.')

# §7: every omitted proof, worked construction, and three projection articles.
p={'O':[0,0,0],'A':[2,0,1],'B':[0,2,1],'A1':[-2,0,-1],'B1':[0,-2,-1]}
m=model(p,[['A','A1'],['B','B1'],['A','B'],['A1','B1']],[['A','B','O'],['A1','B1','O']],{'first':v('Треугольник ABO',polygon=['A','B','O']),'second':v('Треугольник A₁B₁O',polygon=['A1','B1','O'])})
save(7,'центральная симметрия: доказательство и определения',[59,60,61,62,63],'Почему центральная симметрия — движение','Докажи сохранение расстояний при симметрии относительно O; объясни, что такое центр симметрии фигуры и подобие пространственных фигур.',m,[step('Выберем произвольную пару точек','Пусть A,B — любые точки фигуры, A₁,B₁ — их образы. По определению O — середина AA₁ и BB₁: OA=OA₁, OB=OB₁. Для движения требуется доказать AB=A₁B₁ для каждой пары.','neutral'),step('Невырожденный случай','Если A,B,O не коллинеарны, прямые AA₁ и BB₁ задают плоскость. Углы AOB и A₁OB₁ вертикальные и равны. По двум сторонам и углу между ними треугольники ABO и A₁B₁O равны; поэтому AB=A₁B₁.','first'),step('Коллинеарные точки тоже учтём','Если A,B лежат на одной прямой с O, расстояние AB равно либо сумме OA+OB, либо разности большего и меньшего из OA,OB. Симметрия сохраняет эти длины и меняет обе стороны от O одновременно; такая же сумма или разность даёт A₁B₁. Если одна точка — O, равенство следует прямо из определения.','second'),step('Движение и центр фигуры','Итак, центральная симметрия сохраняет все расстояния и является движением. Фигура имеет центр симметрии O, если вместе с каждой X содержит её образ X₁; это требование ко всем точкам, а не к одной паре. Центр шара и центр прямоугольного параллелепипеда — примеры.','neutral'),step('Равенство и подобие вне одной плоскости','Равные фигуры переводятся друг в друга движением; подобные — преобразованием, умножающим все расстояния на одно k>0. Известные признаки равенства треугольников (по двум сторонам и углу; стороне и прилежащим углам; трём сторонам) и подобия (двум углам; двум пропорциональным сторонам и углу; трём пропорциональным сторонам) действуют и для треугольников в разных плоскостях. Учебник здесь формулирует эти факты без новых доказательств.','neutral')],'Сведи произвольную пару точек и центр к одной плоскости; отдельно учти случай одной прямой.')
p={'A':[-3,-1,2],'B':[-3,1,2],'C':[1,1,2],'D':[1,-1,2]}
for k in list(p):x,y,z=p[k];p[k+'1']=[x+.5*y,y,0]
p.update({'E':[3,0,1],'F':[3,0,3],'E1':[3,0,0]})
m=model(p,edgepoly(list('ABCD'))+edgepoly(['A1','B1','C1','D1'])+[[x,x+'1'] for x in 'ABCD']+[['E','F'],['F','E1']],[list('ABCD'),['A1','B1','C1','D1']],{'original':v('Прямоугольник до проекции',polygon=list('ABCD')),'image':v('Параллелограмм после проекции',polygon=['A1','B1','C1','D1']),'collapse':v('Отрезок вдоль проектирования вырождается',segments=[['E','F'],['F','E1']],points=['E1'])})
# This scene uses a single oblique direction (−1/2,0,1), not a point-dependent shear.
for k in 'ABCD':x,y,z=p[k];m['points'][k+'1']=[x+z/2,y,0]
# Tilt the original rectangle about its long side so the oblique projection changes angles.
for k in 'ABCD':x,y,z=p[k];m['points'][k]=[x,.8*y,2+.6*y];m['points'][k+'1']=[x+(2+.6*y)/2,.8*y,0]
m['points'].update({'E':[2.5,0,1],'F':[1.5,0,3],'E1':[3,0,0]})
save(7,'изображения фигур и вырожденные проекции',[63,64,65,66],'Что именно сохраняет изображение','Разбери проекции прямой, многоугольника и окружности; укажи условия, при которых изображение не вырождается.',m,[step('Направление должно пересекать плоскость','Для каждой точки проводят проектирующую прямую одного фиксированного направления, пересекающего плоскость изображения α. Направление, параллельное α, не задаёт проекцию каждой пространственной точки. В модели α горизонтальна, а все проекторы параллельны EF.','neutral'),step('Укажем вырождение','Прямая вдоль проектирования даёт одну точку; здесь весь EF отображается в E₁. Если направление проектирования параллельно плоскости многоугольника или лежит в ней, его изображение может стать отрезком.','collapse'),step('Невырожденные многоугольники','При невырожденной проекции треугольник остаётся треугольником, параллелограмм — параллелограммом, трапеция — трапецией. Параллельность и отношения на одной прямой либо параллельных прямых сохраняются; равенство произвольно направленных сторон и прямые углы вообще не сохраняются.','image'),step('Особые виды и окружность','Равнобедренный треугольник может стать разносторонним; квадрат — неквадратным параллелограммом; равнобокая или прямоугольная трапеция может потерять свой особый вид. Невырожденная проекция окружности — эллипс (в частном случае окружность); её центр переходит в центр эллипса. При проектировании вдоль её плоскости получается отрезок.','original')],'Условия невырождения нужно проверить до утверждения, что рисунок остаётся многоугольником.')
p={'A':[-2,0,2],'B':[2,0,3],'X':[0,0,2.5],'A1':[-1,0,0],'B1':[3.5,0,0],'X1':[1.25,0,0],'P':[-2,-1,0],'Q':[4,-1,0],'R':[4,1,0],'S':[-2,1,0]}
m=model(p,[['A','B'],['A1','B1'],['A','A1'],['B','B1'],['X','X1']],[['P','Q','R','S'],['A','B','B1','A1']],{'sweep':v('Плоскость проектирующих прямых β',polygon=['A','B','B1','A1']),'segment':v('Точка между концами и её образ',segments=[['A','B'],['A1','B1'],['X','X1']],points=['X','X1'])},labels=['A','B','X','A1','B1','X1'])
save(7,'доказательство теоремы 7.1',[64,75,76],'Почему прямая проектируется в прямую','Докажи: прямая a, не параллельная направлению проектирования l, проектируется в прямую a₁, а отрезок AB — в отрезок A₁B₁.',m,[step('Соберём проекторы в плоскость','Все прямые, параллельные l и пересекающие a, лежат в одной плоскости β по задаче §4. Плоскость β пересекает α, поскольку содержит проектирующие прямые. Обозначим её след a₁=α∩β.','sweep'),step('Каждый образ лежит на следе','Для X∈a проектор лежит в β, а его точка X₁ пересечения с α — в α∩β=a₁. Поэтому проекция a содержится в a₁.','sweep'),step('Не потеряем точки прямой a₁','Для любой Y∈a₁ проведём в β прямую через Y параллельно l. Она не параллельна a, поэтому пересекает a в X. Проекция X равна Y. Получили и обратное включение: вся a₁ является образом a.','sweep'),step('Почему получается весь отрезок','В одной плоскости β параллельные проекторы сохраняют порядок точек на двух пересекаемых прямых: если X между A,B, его образ между A₁,B₁, и наоборот. Это следует из теоремы о пропорциональных отрезках в планиметрии (отношение внутренних частей положительно). Поэтому образ AB — ровно A₁B₁. Направление вдоль a исключено: тогда образ был бы точкой.','segment')],'Докажи два включения для прямой, а для отрезка дополнительно проверь расположение между концами.')
p={'A':[-2,-1,2],'B':[2,-1,2],'C':[-2,1,3],'D':[2,1,3],'A1':[-1,-1,0],'B1':[3,-1,0],'C1':[-.5,1,0],'D1':[3.5,1,0]}
m=model(p,[['A','B'],['C','D'],['A1','B1'],['C1','D1']]+[[x,x+'1'] for x in 'ABCD'],[['A','B','B1','A1'],['C','D','D1','C1']],{'planes':v('Две плоскости проекторов',segments=[['A','B'],['C','D'],['A','A1'],['C','C1']]),'traces':v('Параллельные следы',segments=[['A1','B1'],['C1','D1']])})
save(7,'доказательство теоремы 7.2',[64,65,76,77,78],'Параллельные или совпадающие образы','Параллельные a,b не направлены вдоль проектирования. Докажи, что их образы — параллельные или совпадающие прямые.',m,[step('Введём общую плоскость','Через a,b проходит плоскость γ. Сравним направление проектирования l с γ. Если оно принадлежит направлению γ, все проекторы обеих прямых лежат в γ.','neutral'),step('Первый случай: одна прямая изображения','В этом случае оба образа по теореме 7.1 совпадают со следом γ∩α. Это возможно и при различных a,b. Сцена показывает следующий, невырожденный для γ случай; данный случай описан отдельно.','neutral'),step('Второй случай: две плоскости проекторов','Если l пересекает γ, плоскости βa и βb, образованные a,b и направлением l, различны. В каждой есть две пересекающиеся прямые: a и AA₁, b и CC₁. Они соответственно параллельны, поэтому по признаку 6.1 βa∥βb.','planes'),step('Их следы параллельны','Плоскость изображения α пересекает эти параллельные плоскости по a₁,b₁. Теорема 6.3 даёт a₁∥b₁. Для отрезков на a,b это означает параллельные или коллинеарные отрезки-образы.','traces')],'Рассмотри, проектируется ли вся плоскость исходных параллелей в прямую или в плоскую фигуру.')
