save(7,'задача: изображение высоты равнобокой трапеции',[66,67],'Высота на перспективном рисунке','A₁B₁C₁D₁ — невырожденное изображение равнобокой трапеции ABCD, BC∥AD. Построй изображение высоты BK, опущенной из B на AD.',m,[step('Найдём направление в исходной фигуре','Обозначим M середину AD, N середину BC. В равнобокой трапеции MN — ось симметрии и перпендикулярно основаниям. Поэтому BK∥MN.','original'),step('Построим образы середин','По 7.3 M₁ и N₁ — середины соответственно A₁D₁ и B₁C₁. Их можно построить прямо на данном изображении, затем соединить.','midpoints'),step('Перенесём параллельность','Через B₁ проведём прямую параллельно M₁N₁ до пересечения K₁ с A₁D₁. По 7.2 это и есть изображение прямой BK; по 7.1 получаем изображение её отрезка B₁K₁.','height'),step('Не подменим изображение высотой рисунка','B₁K₁ вообще не перпендикулярно A₁D₁ на рисунке. Построить обычный перпендикуляр на изображении было бы ошибкой: сохраняется нужная параллельность, а не прямой угол.','height')],'Проведи линию через середины оснований; в исходной равнобокой трапеции она параллельна высоте.')
m=box();p={k:[xyz[0]+.4*xyz[1],xyz[2]+.3*xyz[1],0] for k,xyz in m['points'].items()};m=model(p,m['edges'],views={'red':v('Группа красных точек: A,D,C,C₁',points=['A','D','C','C1']),'blue':v('Группа синих точек: B,A₁,B₁,D₁',points=['B','A1','B1','D1']),'example':v('Один из нужных параллелограммов',polygon=['A','D','C','B'])})
save(7,'спроектируем на плоскость: восемь цветных точек',[73],'Восемь точек из проекции куба','Расположи на плоскости четыре красные и четыре синие точки так, чтобы любые три точки одного цвета вместе с некоторой точкой другого цвета были вершинами параллелограмма.',m,[step('Выберем восемь вершин куба','У куба ABCDA₁B₁C₁D₁ окрасим A,D,C,C₁ красным, а B,A₁,B₁,D₁ — синим. Эти группы не являются чередующейся шахматной раскраской: красные образуют путь A→D→C→C₁ по трём рёбрам.','red'),step('Проверим все красные тройки','Тройка A,D,C дополняется точкой B; A,D,C₁ — точкой B₁; A,C,C₁ — точкой A₁; D,C,C₁ — точкой D₁. В каждом случае в кубе получается параллелограмм: противоположные стороны равны и параллельны.','example'),step('Проверим все синие тройки','B,A₁,B₁ дополняется A; B,A₁,D₁ — C; B,B₁,D₁ — D; A₁,B₁,D₁ — C₁. Это четыре оставшиеся тройки; проверка обеих групп исчерпывает условие «любые три».','blue'),step('Спроектируем без совпадений','Выбираем направление, при котором восемь образов различны и перечисленные параллелограммы не вырождаются. На модели приведено такое плоское изображение куба. Параллельная проекция сохраняет параллелограммы, поэтому та же раскраска восьми плоских точек решает задачу. Цвет задаётся перечисленными группами; выделение переключает проверяемую группу.','neutral')],'Ищи пространственную фигуру с большим числом параллелограммов, затем проверь все четыре тройки каждого цвета.',caption='Плоская проекция куба. Красная группа: A,D,C,C₁; синяя: B,A₁,B₁,D₁. Цвета заданы этим перечнем, а переключаемое выделение показывает проверяемую группу.')
# A regular pentagon in a tilted plane, orthogonally projected to z=0.
p={}
for i,k in enumerate('ABCDE'):
 t=math.pi/2+2*math.pi*i/5;x=2*math.cos(t);y=2*math.sin(t);p[k]=[x,.6*y,3+.8*y];p[k+'1']=[x,.6*y,0]
def cross2(a,b):return a[0]*b[1]-a[1]*b[0]
def intersect(a,b,c,d):
 u=[b[i]-a[i] for i in range(2)];w=[d[i]-c[i] for i in range(2)];delta=[c[i]-a[i] for i in range(2)];t=cross2(delta,w)/cross2(u,w);return lerp(a,b,t)
p['K']=intersect(p['A'],p['C'],p['B'],p['D']);p['L']=intersect(p['A'],p['C'],p['B'],p['E']);p['K1']=[p['K'][0],p['K'][1],0];p['L1']=[p['L'][0],p['L'][1],0]
m=model(p,edgepoly(list('ABCDE'))+edgepoly([k+'1' for k in 'ABCDE'])+[['A','C'],['B','D'],['B','E'],['A1','C1'],['B1','D1'],['B1','E1']]+[[k,k+'1'] for k in 'ABCDE'],[list('ABCDE'),[k+'1' for k in 'ABCDE']],{'original':v('Правильный пятиугольник в наклонной плоскости',polygon=list('ABCDE')),'diagonal':v('Три части диагонали и их образы',segments=[['A','C'],['A1','C1']],points=['K','L','K1','L1']),'image':v('Неправильный пятиугольник с теми же отношениями',polygon=[k+'1' for k in 'ABCDE'])})
save(7,'спроектируем на плоскость: пятиугольник',[73,74],'Те же отношения без правильности','В правильном пятиугольнике диагонали делятся другими диагоналями в отношении 1:λ:1, где λ=(√5−1)/2. Существует ли неправильный пятиугольник с тем же свойством каждой диагонали?',m,[step('Возьмём известную правильную фигуру','У правильного ABCDE две внутренние точки пересечения делят каждую диагональ на три части в указанном отношении. Это свойство правильного пятиугольника дано в условии статьи.','original'),step('Спроектируем на наклонённую плоскость','Выберем невырожденную параллельную проекцию, которая изменяет длины в разных направлениях по-разному. В модели исходный пятиугольник правильный, а его ортогональная проекция на горизонтальную плоскость сжимает одно направление.','image'),step('Сохраним каждое отношение','На любой отдельной диагонали все три части коллинеарны. По 7.3 их отношения сохраняются. По 7.1 точки пересечения остаются точками пересечения соответствующих диагоналей. Поэтому на каждой диагонали изображения снова получаем 1:λ:1.','diagonal'),step('Проверим, что образ неправильный','В показанной конфигурации соседние стороны A₁B₁ и B₁C₁ имеют различные длины (исходные стороны равны). Следовательно пятиугольник неправильный, но все требуемые отношения выполнены. Ответ: да.','image')],'Проекция сохраняет отношения внутри одной диагонали, хотя равенство разных сторон может исчезнуть.')
# The six central vertices of the six-cevian arrangement in barycentric coordinates.
A=[-3,0,0];B=[3,0,0];C=[-1,4,0];D=[0,0,3*SQ(3)]
def affine(x,y,top):return [A[i]+x/6*(B[i]-A[i])+y/6*(top[i]-A[i]) for i in range(3)]
coords={'K':(1.5,1.5),'L':(1.2,2.4),'M':(1.5,3),'N':(2.4,2.4),'O':(3,1.5),'P':(2.4,1.2),'G':(2,2),'U':(4,2),'V':(2,4),'W':(0,4),'X':(0,2),'Y':(2,0),'Z':(4,0)}
p={'A':A,'B':B,'C':C,'D':D}
for k,(x,y) in coords.items():p[k]=affine(x,y,C);p[k+'1']=affine(x,y,D)
cevs=[['A','U'],['A','V'],['B','W'],['B','X'],['C','Y'],['C','Z']]
projected=[['A','U1'],['A','V1'],['B','W1'],['B','X1'],['D','Y1'],['D','Z1']]
m=model(p,edgepoly(['A','B','C'])+edgepoly(['A','B','D'])+cevs+projected+[['K','N'],['L','O'],['M','P'],['K1','N1'],['L1','O1'],['M1','P1'],['C','D']],[['A','B','C'],['A','B','D']],{'original':v('Шесть чевиан и внутренний шестиугольник',polygon=list('KLMNOP')),'regular':v('Равносторонний треугольник ABD',polygon=['A','B','D']),'concurrent':v('Три оси симметрии и общий центр',segments=[['K1','N1'],['L1','O1'],['M1','P1']],points=['G1']),'back':v('Три диагонали исходного шестиугольника',segments=[['K','N'],['L','O'],['M','P']],points=['G'])},labels=['A','B','C','D','K','L','M','N','O','P','G','K1','L1','M1','N1','O1','P1','G1'])
save(7,'спроектируем на плоскость: шесть чевиан',[74,75],'Три диагонали встречаются в одной точке','Каждую сторону произвольного треугольника ABC разделили на три равные части. Соединили вершины с обеими точками трисекции противоположных сторон; получился внутренний шестиугольник KLMNOP. Докажи, что KN,LO,MP проходят через одну точку.',m,[step('Построим удобный пространственный образ','Выберем равносторонний треугольник ABD в другой плоскости с общей стороной AB. Спроектируем плоскость ABC на ABD параллельно CD. Точки A,B остаются на месте, C переходит в D; направление CD не лежит ни в одной из двух плоскостей, поэтому эта проекция взаимно однозначна на ABC.','regular'),step('Сохраним всё построение','По 7.3 точки трисекции переходят в точки трисекции; по 7.1 шесть проведённых отрезков и их пересечения переходят в такие же шесть отрезков и вершины внутреннего шестиугольника равностороннего треугольника.','original'),step('Используем симметрию равностороннего случая','Каждая из трёх осей симметрии равностороннего треугольника переставляет шесть чевиан и проходит через пару противоположных вершин внутреннего шестиугольника. Поэтому три его противоположные диагонали лежат на трёх медианах ABD и встречаются в центре G₁.','concurrent'),step('Вернём общую точку','Обратное проектирование параллельно CD переносит G₁ в единственную точку G плоскости ABC. Поскольку G₁ принадлежит всем трём диагоналям изображения, G принадлежит KN,LO,MP. Значит, эти три прямые конкурентны — имеют одну общую точку.','back')],'У равностороннего треугольника помогают три оси симметрии; параллельная проекция переносит всю конструкцию.')

