save(8,'доказательство теоремы 8.1 и замечание',[83,84],'Почему перенос направлений сохраняет угол','Прямые a,b пересекаются в M; a₁,b₁ пересекаются в M₁; a∥a₁, b∥b₁. Докажи равенство углов между парами прямых.',m,[step('Сначала случай одной плоскости','Если обе пары лежат в одной плоскости, угол между прямыми не меняется при замене стороны на параллельную: соответствующие или накрест лежащие углы равны, а смежные дают один и тот же меньший угол между прямыми.','neutral'),step('Соединим пары соответствующих точек','Для различных плоскостей выберем A∈a, B∈b и проведём AA₁∥MM₁, BB₁∥MM₁ до A₁∈a₁, B₁∈b₁. Четырёхугольники MAA₁M₁ и MBB₁M₁ — параллелограммы.','bridges'),step('Получим третью пару равных сторон','Отсюда MA=M₁A₁, MB=M₁B₁, а AA₁ и BB₁ равны и одинаково направлены. Поэтому AA₁B₁B — параллелограмм и AB=A₁B₁.','bridges'),step('Сравним треугольники','Треугольники MAB и M₁A₁B₁ равны по трём сторонам. Следовательно ∠AMB=∠A₁M₁B₁; меньшие углы между соответствующими прямыми также равны. Определение угла скрещивающихся прямых поэтому не зависит от точки переноса.','triangles'),step('Можно перенести только одну прямую','Для скрещивающихся a,b выберем точку M на a и через неё проведём b₁∥b. В определении угла допускается именно эта точка M; направление a уже проходит через неё. Поэтому достаточно вычислить угол a с b₁.','neutral')],'Дострой три параллелограмма и сравни треугольники по трём сторонам.')
m=box();m['edges'] += [['A1','D'],['D1','C'],['A1','B'],['B','D']];view(m,'replace','A₁B параллельна D₁C',segs=[['A1','B'],['D1','C']]);view(m,'triangle','Равносторонний A₁BD',poly=['A1','B','D'])
save(8,'задача: угол диагоналей граней куба',[85],'Угол между A₁D и D₁C','В кубе ABCDA₁B₁C₁D₁ найди угол между прямыми A₁D и D₁C.',m,[step('Перенесём одну прямую','Плоскость A₁D₁CB пересекает параллельные плоскости ABB₁A₁ и DCC₁D₁ по параллельным прямым A₁B и D₁C. Поэтому можно заменить D₁C на A₁B.','replace'),step('Выделим плоский треугольник','Искомый угол теперь — меньший угол между A₁D и A₁B. Соединим B и D. Отрезки A₁D,A₁B,BD — диагонали равных квадратных граней, поэтому все три равны.','triangle'),step('Найдём угол','Треугольник A₁BD равносторонний, значит ∠DA₁B=60°. Это угол меньше90°, поэтому он и является углом между исходными прямыми. Ответ:60°.','triangle')],'Замени одну скрещивающуюся прямую параллельной через A₁; затем найди равносторонний треугольник.')

# §9.
p={'O':[0,0,0],'A':[3,0,0],'B':[0,3,0],'X':[1.5,1.5,0],'M':[0,0,2],'N':[0,0,-2],'P':[-1,-1,0],'Q':[4,-1,0],'R':[4,4,0],'S':[-1,4,0]}
m=model(p,[['O','A'],['O','B'],['A','B'],['O','X'],['M','N'],['M','A'],['N','A'],['M','B'],['N','B'],['M','X'],['N','X']],[['P','Q','R','S']],{'first':v('Равные треугольники MAB и NAB',segments=[['M','A'],['N','A'],['M','B'],['N','B'],['A','B']]),'second':v('Равные треугольники MBX и NBX',segments=[['M','B'],['N','B'],['B','X'],['M','X'],['N','X']]),'median':v('Медиана XO — высота в равнобедренном MXN',polygon=['M','X','N'],segments=[['O','X']])},labels=['O','A','B','X','M','N'])
save(9,'доказательство теоремы 9.1',[88,89,90],'От двух направлений — ко всей плоскости','Докажи: если c перпендикулярна двум пересекающимся прямым a,b плоскости α, то c⊥α.',m,[step('Сведём проверку к общей точке','Пусть a∩b={O}. Для любой x⊂α, параллельной a или b, уже известно c⊥x. В остальных случаях через O проведём c₁∥c и x₁∥x (при прохождении через O берём сами прямые). Достаточно доказать c₁⊥x₁.','neutral'),step('Сделаем симметричную пару','Выберем A∈a, B∈b так, чтобы отрезок AB пересекал x₁ во внутренней точке X≠O. На c₁ отметим M,N по разные стороны O с OM=ON. Из c₁⊥a,b следует AM=AN и BM=BN: в прямоугольных треугольниках равны катеты.','first'),step('Первая пара треугольников','У MAB и NAB равны все три стороны: AM=AN, BM=BN, AB общая. Поэтому ∠MBX=∠NBX, поскольку X находится на отрезке BA.','first'),step('Вторая пара треугольников','В MBX и NBX равны BM=BN, общая BX и углы между этими сторонами. По двум сторонам и углу между ними треугольники равны, откуда XM=XN.','second'),step('Медиана становится высотой','MXN равнобедренный, O — середина MN. Поэтому медиана XO перпендикулярна MN: x₁⊥c₁. Параллельный перенос направлений даёт x⊥c. Так как x была произвольной, по определению c⊥α.','median'),step('Почему перпендикуляр обязательно пересекает плоскость','Если c лежала бы в α или была параллельна α, в α нашлась бы прямая, параллельная c. Угол с ней был бы0°, вопреки перпендикулярности каждой прямой α. Значит, c пересекает α ровно в одной точке. Отрезок называют перпендикулярным плоскости, если ей перпендикулярна содержащая его прямая.','neutral')],'Для произвольного направления x сравни расстояния до двух точек M,N, симметричных относительно O.')
p={'A':[0,0,0],'A1':[0,0,3],'B':[2,0,0],'M':[2,0,3],'C':[3,0,0],'P':[-1,-1,0],'Q':[4,-1,0],'R':[4,2,0],'S':[-1,2,0]}
m=model(p,[['A','A1'],['B','M'],['M','C'],['B','C']],[['P','Q','R','S']],{'normals':v('Две настоящие нормали',segments=[['A','A1'],['B','M']]),'candidate':v('MC показывает, почему второе основание не подходит',polygon=['M','B','C'])},labels=['A','A1','B','M','C'])
save(9,'доказательство теоремы 9.3 и единственность',[90,91],'Два перпендикуляра одной плоскости параллельны','Докажи, что две различные прямые a,b, перпендикулярные α, параллельны. Модель: a=AA₁, b=BM; наклонная MC показана только для проверки невозможного второго основания.',m,[step('Предположим непараллельность','Пусть a и b не параллельны. Выберем M∈b вне α и вне a. Через M проведём b₁∥a. По теореме 9.2 b₁⊥α. При нашем предположении b₁≠b.','normals'),step('Получим два различных основания','Обозначим B=b∩α, B₁=b₁∩α. Если B=B₁, прямые b,b₁ проходили бы через две точки M и B, то есть совпали бы. Значит, B≠B₁.','candidate'),step('Придём к плоской невозможности','В плоскости MBB₁ обе различные прямые MB и MB₁ перпендикулярны BB₁⊂α. Но через точку M одной плоскости проходит лишь один перпендикуляр к BB₁. Противоречие. На модели возможная вторая линия MC действительно не перпендикулярна BC, поэтому она не может быть второй нормалью.','candidate'),step('Сформулируем следствия','Следовательно a∥b. Это же рассуждение доказывает, что через внешнюю точку проходит не более одной нормали к плоскости. Теорема 9.4 утверждает существование и единственность нормали через любую точку; в учебнике она приведена без доказательства, её формулировка разобрана в обзоре §9.','normals')],'Через M проведи параллель первой нормали и попробуй получить два перпендикуляра к одной прямой в одной плоскости.',caption='AA₁ и BM — настоящие перпендикуляры к горизонтальной плоскости. MC — наклонная, демонстрирующая невозможность второго основания; она не объявляется перпендикуляром.')

