 overview=OUT/f'theory-{p:02}.json';old=json.loads(overview.read_text());added=[x for x in CARDS if x['paragraph']==p]
 mapped=[{'component':name,'printedPages':pages,'pdfPages':[i+1 for i in pages],'coveredBy':[{'lessonId':old['id'],'stepIds':[f'step-{i}' for i in ids]}]} for name,pages,ids in COMPONENTS[p]]
