 entries.append({'sourceId':f'source-theory-{p:02}','paragraph':p,'printedPages':pages,'pdfPages':[i+1 for i in pages],'requiredParts':['обзор']+[x['part'] for x in added],'coverage':'source components mapped to draft lessons; independent review pending','inventoryComplete':True,'components':mapped,'overview':{'file':str(overview.relative_to(R)),'lessonId':old['id'],'sha256':hashlib.sha256(overview.read_bytes()).hexdigest()},'addedLessons':added,'remainingComponents':[]})
